from pathlib import Path
import base64

MASK_B64 = ''''''

asset = Path('assets/demo/Masque_SCR.webp')
asset.parent.mkdir(parents=True, exist_ok=True)
asset.write_bytes(base64.b64decode(MASK_B64))

p = Path('index.html')
text = p.read_text(encoding='utf-8')
old = "assets/demo/vibex_mask_16.png"
new = "assets/demo/Masque_SCR.webp"
assert old in text, 'Current VIBEX noise-mask reference not found'
text = text.replace(old, new)
p.write_text(text, encoding='utf-8')

# Sanity checks.
raw = asset.read_bytes()
assert raw[:4] == b'RIFF' and raw[8:12] == b'WEBP'
assert new in p.read_text(encoding='utf-8')
print('OK - VIBEX texture mask installed')
